#!/usr/bin/env python3
"""Mechanical translation of committed DCTLs; do not edit generated C++."""
import re,json,csv,math,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[2]
UI=[]
film_bases=json.loads((ROOT/'docs/data/ofx_film_bases.json').read_text())
assert film_bases and len({p['stock'] for p in film_bases})==len(film_bases),'Exactly one Base per stock'
assert all(p['label'].endswith(' Base') and p['stops'][1]==0 for p in film_bases)
base_rows=['{"None",0.f,0.f,0.f}']
for p in film_bases:base_rows.append('{"'+p['label']+'",'+','.join(f'{float(v)}f' for v in p['stops'])+'}')
(ROOT/'ofx/src/film_bases.hpp').write_text('// Generated from docs/data/ofx_film_bases.json. One measured Base per stock.\n#pragma once\nnamespace nss {\nstruct FilmBase {const char *label;float r,g,b;};\ninline constexpr FilmBase filmBases[]={'+','.join(base_rows)+'};\ninline FilmBase filmBaseGains(int index){return index>0&&index<int(sizeof(filmBases)/sizeof(filmBases[0]))?filmBases[index]:filmBases[0];}\n}\n')
out=['// Generated by ofx/tools/generate.py from DCTL templates.\n#pragma once\n#include <cmath>\n#include "film_bases.hpp"\nnamespace nss {\nstruct Vec3 { float x,y,z; };\ninline Vec3 make_float3(float x,float y,float z) {return {x,y,z};}\n']
for ns,file in [('Density','template.dctl'),('Positive','template_core.dctl')]:
 text=(ROOT/file).read_text()
 if ns=='Density':
  text=text.replace('@@PRESET_HEADER@@','').replace('@@PRESET_FUNC@@','')
  text=text.replace('preset_base(preset, make_float3(base_r, base_g, base_b))','make_float3(base_r, base_g, base_b)')
 if ns=='Positive':
  text=text.replace('@@WB_HEADER@@','DEFINE_UI_PARAMS(film_wb, Film white balance, DCTLUI_COMBO_BOX, 1, {NONE, BASE}, {None, '+', '.join(p['label'] for p in film_bases)+'})').replace('@@WB_FUNC@@','')
  # Base dropdown loads visible balance sliders; no hidden preset gain/slope.
  text,count=re.subn(r'    float ar = 0\.0f;.*?(?=    float gr_c = gray_r;)', '    float ar = 0.0f;\n    float ag = 0.0f;\n    float ab = 0.0f;\n',text,flags=re.S)
  assert count==1,'Positive WB template changed'
  # Saved user gray-points are data, not intrinsic DCTL presets. Manual gray fields cover them.
  text=re.sub(r'    if \(use_gray == 0 && film_wb >= 2\).*?    }\n','',text,flags=re.S)
 fields=[]
 def param(m):
  a=[s.strip() for s in m.group(1).split(',')];name,label,typ,default=a[:4]
  if ns=='Positive' and name in ('bal_r','bal_g','bal_b'):default=str(float(film_bases[0]['stops']['rgb'.index(name[-1])]))
  kind='float' if typ=='DCTLUI_SLIDER_FLOAT' else 'int'
  fields.append(f'    {kind} {name} = {default}{"f" if kind=="float" else ""};')
  options=[]
  if typ=='DCTLUI_COMBO_BOX':options=re.findall(r'\{([^}]+)\}',m.group(1))[1].split(',')
  UI.append(dict(stage=ns,name=name,label=label,kind=kind,default=float(default),type=typ,min=float(a[4]) if kind=='float' else 0,max=float(a[5]) if kind=='float' else 1,step=float(a[6]) if kind=='float' else 1,options=[o.strip() for o in options]))
  return ''
 text=re.sub(r'^DEFINE_UI_PARAMS\((.*)\)\s*$',param,text,flags=re.M)
 text=text.replace('__DEVICE__ ','').replace('float3','Vec3').replace('make_Vec3','make_float3')
 for f in ['exp2','exp','log2','log','pow','tanh','fmin','fmax']:
  text=text.replace('_'+f+'f','std::'+f)
 out.append('struct '+ns+' {\n'+'\n'.join(fields)+'\n'+text+'\n};\n')
out.append('}\n')
(ROOT/'ofx/src/dctl_math.hpp').write_text(''.join(out))
(ROOT/'ofx/src/parameters.json').write_text(json.dumps(UI,indent=2)+'\n')
(ROOT/'ofx/src/pipeline_equal.inc').write_text(' &&\n'.join(f'a.{p["stage"].lower()}.{p["name"]}==b.{p["stage"].lower()}.{p["name"]}' for p in UI)+' &&\n')
# Template-derived controls, followed by explicit plugin default/group overrides.
lines=['// Generated DCTL UI descriptors\n']
for p in UI:
 if p['stage']=='Density' and p['name'].startswith('cast_'):continue
 key=p['stage'].lower()+'_'+p['name'];opts='|'.join(p['options'])
 kind={'DCTLUI_SLIDER_FLOAT':'Number','DCTLUI_CHECK_BOX':'Boolean','DCTLUI_COMBO_BOX':'Choice'}[p['type']]
 group='balance' if p['stage']=='Density' and p['name'].startswith('base_') else p['stage'].lower()
 default=.5 if p['stage']=='Density' and p['name'].startswith('base_') else .9 if key=='positive_expo' else p['default']
 lines.append(f'{{"{key}","{p["label"]}",Kind::{kind},{default},{p["min"]},{p["max"]},{p["step"]},"{opts}","{group}"}},\n')
 if key=='positive_gam_b':lines.append('{"gamma_scale","Gamma scale",Kind::Number,1.15,0.25,2.0,0.01,"","positive"},\n')
(ROOT/'ofx/src/parameter_defs.inc').write_text(''.join(lines))
(ROOT/'ofx/src/read_params.inc').write_text('// Generated\n'+''.join(f'p.{p["stage"].lower()}.{p["name"]} = {"number" if p["kind"]=="float" else "integer"}(set,"{p["stage"].lower()}_{p["name"]}",time);\n' for p in UI if not (p['stage']=='Density' and p['name'].startswith('cast_'))))

(ROOT/'ofx/tests/json_params.inc').write_text('// Generated\n'+''.join(f'if(j.contains("{p["stage"].lower()}") && j.at("{p["stage"].lower()}").contains("{p["name"]}")) p.{p["stage"].lower()}.{p["name"]} = j.at("{p["stage"].lower()}").at("{p["name"]}").get<{p["kind"]}>();\n' for p in UI if not (p['stage']=='Density' and p['name'].startswith('cast_'))))

def integrate(stock,k):
 sums=[0.,0.,0.]
 with (ROOT/f'colorsci/data/{stock}_log_sensitivity.csv').open() as f:
  for row in list(csv.reader(f))[1:]:
   nm=float(row[0]);spd=(550/nm)**5*math.expm1(1.438776877e7/(550*k))/math.expm1(1.438776877e7/(nm*k))
   for c in range(3):
    if row[c+1]:sums[c]+=10**float(row[c+1])*10*spd
 return sums
presets=[]
for film,stock,neutral,gamma in [('T',5219,3200,[.4482,.5266,.5096]),('D',5207,5600,[104/180/1.2,121/180/1.2,117/180/1.2])]:
 ref=integrate(stock,neutral)
 for k in [3200,3800,4400,5000,5600]:
  e=integrate(stock,k);logs=[math.log10(e[c]/ref[c]) for c in range(3)];d=[-gamma[c]*(logs[c]-logs[1]) for c in range(3)]
  presets.append(dict(film=film,stock=stock,kelvin=k,offset=d,gamma=gamma,neutral=neutral))
(ROOT/'ofx/src/wb_presets.hpp').write_text('// Generated Planck x Kodak nominal ECN-2 offsets.\n#pragma once\nnamespace nss {\ninline constexpr float wbOffsets[2][5][3] = {\n'+',\n'.join('{'+','.join('{'+','.join(f'{v:.9f}f' for v in p['offset'])+'}' for p in presets[i*5:i*5+5])+'}' for i in range(2))+'\n};\n}\n')
(ROOT/'docs/data/ofx_wb_presets.json').write_text(json.dumps(presets,indent=2)+'\n')
(ROOT/'docs/data/ofx_0901_base_presets.json').write_text(json.dumps([dict(p,baseline=[.5,.5,.5],base=[.5*10**v for v in p['offset']]) for p in presets],indent=2)+'\n')
print('Generated DCTL math,',len(UI),'parameters, 10 illuminant presets')
# Embed the portable OpenCL kernel without runtime file dependencies.
math=(ROOT/'ofx/src/render_math.h').read_text()
prefix='''#define NSS_PARAMS __constant const float *
#define NSS_EXP exp
#define NSS_EXP2 exp2
#define NSS_LOG log
#define NSS_LOG2 log2
#define NSS_POW pow
#define NSS_TANH tanh
#define NSS_MIN fmin
#define NSS_MAX fmax
'''
kernel=prefix+math+(ROOT/'ofx/src/render.cl').read_text()
(ROOT/'ofx/src/opencl_source.hpp').write_text('#pragma once\nnamespace nss {inline constexpr const char *openclSource=R"NSSCL('+kernel+')NSSCL";}\n')
